import{_ as t,o as i,c as a,ae as o}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Audit Event Schema and Append-Only Sink","description":"","frontmatter":{"work_package_id":"WP01","title":"Audit Event Schema and Append-Only Sink","lane":"done","dependencies":[],"base_branch":"main","base_commit":"c0c76ff4c8f9336ace18d5c5929a53f91b36e7a8","created_at":"2026-03-01T13:29:53.391826+00:00","subtasks":["T001","T002","T003","T004"],"phase":"Phase 1 - Audit Foundation","assignee":"","agent":"claude-haiku","shell_pid":"55466","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/024-audit-logging-and-session-replay/tasks/WP01-audit-event-schema-and-sink.md","filePath":"specs/024-audit-logging-and-session-replay/tasks/WP01-audit-event-schema-and-sink.md"}'),s={name:"specs/024-audit-logging-and-session-replay/tasks/WP01-audit-event-schema-and-sink.md"};function l(n,e,r,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="work-package-prompt-wp01-audit-event-schema-and-append-only-sink" tabindex="-1">Work Package Prompt: WP01 - Audit Event Schema and Append-Only Sink <a class="header-anchor" href="#work-package-prompt-wp01-audit-event-schema-and-append-only-sink" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Audit Event Schema and Append-Only Sink&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Define the structured audit event schema with all fields required for forensic analysis.</li><li>Implement an append-only sink that never blocks command execution and never drops events.</li><li>Subscribe to bus events for automatic audit capture.</li></ul><p>Success criteria:</p><ul><li>All audit events conform to the defined schema with required fields.</li><li>Write latency &lt; 5ms (p95) to avoid blocking command execution.</li><li>Zero events dropped under simulated backpressure or write failures.</li><li>Bus subscription captures lifecycle events automatically.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/spec.md</code></li></ul><p>Constraints:</p><ul><li>Async writes; never block the hot path.</li><li>Append-only: no mutation or deletion except via retention purge.</li><li>Events must never be dropped; buffer on failure and retry.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-define-auditevent-schema" tabindex="-1">Subtask T001 - Define AuditEvent schema <a class="header-anchor" href="#subtask-t001-define-auditevent-schema" aria-label="Permalink to &quot;Subtask T001 - Define AuditEvent schema&quot;">​</a></h3><ul><li>Purpose: Establish the immutable record format for all audit events, providing the foundation for the entire audit system.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/event.ts</code>.</li><li>Define <code>AuditEvent</code> interface with all required fields: <ul><li><code>id</code>: unique string (UUID v7 for time-ordered generation)</li><li><code>eventType</code>: string categorization (e.g., <code>&quot;command.executed&quot;</code>, <code>&quot;policy.evaluation&quot;</code>, <code>&quot;session.created&quot;</code>, <code>&quot;terminal.output&quot;</code>, <code>&quot;approval.resolved&quot;</code>)</li><li><code>actor</code>: string identifying who performed the action (agent ID, operator ID, or system)</li><li><code>action</code>: string describing what was done (e.g., <code>&quot;execute&quot;</code>, <code>&quot;create&quot;</code>, <code>&quot;approve&quot;</code>, <code>&quot;deny&quot;</code>)</li><li><code>target</code>: string identifying what was affected (file path, session ID, command text)</li><li><code>result</code>: string (e.g., <code>&quot;success&quot;</code>, <code>&quot;failure&quot;</code>, <code>&quot;denied&quot;</code>, <code>&quot;timeout&quot;</code>)</li><li><code>timestamp</code>: ISO 8601 with millisecond precision</li><li><code>workspaceId</code>: string</li><li><code>laneId</code>: optional string</li><li><code>sessionId</code>: optional string</li><li><code>correlationId</code>: string linking related events across the system</li><li><code>metadata</code>: Record&lt;string, unknown&gt; for event-type-specific data</li></ul></li><li>Define <code>AuditEventInput</code> type for creating events (omitting auto-generated fields like <code>id</code> and <code>timestamp</code>).</li><li>Implement <code>createAuditEvent(input: AuditEventInput): AuditEvent</code> factory function that generates the ID (UUID v7) and timestamp.</li><li>Implement <code>validateAuditEvent(event: AuditEvent): boolean</code> that checks all required fields are present and correctly typed.</li><li>Define event type constants for all known event categories to prevent typos.</li><li>Add JSDoc documentation for every field and type.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/event.ts</code></li></ul></li><li>Acceptance: <ul><li>Schema covers all required fields per spec FR-024-001.</li><li>Factory function generates valid events.</li><li>Validation catches malformed events.</li><li>All types documented.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-append-only-auditsink" tabindex="-1">Subtask T002 - Implement append-only AuditSink <a class="header-anchor" href="#subtask-t002-implement-append-only-auditsink" aria-label="Permalink to &quot;Subtask T002 - Implement append-only AuditSink&quot;">​</a></h3><ul><li>Purpose: Provide the write interface for audit events with guaranteed delivery and non-blocking behavior.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/sink.ts</code>.</li><li>Define <code>AuditSink</code> interface: <ul><li><code>write(event: AuditEvent): Promise&lt;void&gt;</code> — async, non-blocking, never throws (buffers on failure).</li><li><code>flush(): Promise&lt;void&gt;</code> — force-flush any buffered events.</li><li><code>getBufferedCount(): number</code> — return count of events waiting to be persisted.</li></ul></li><li>Implement <code>DefaultAuditSink</code> class: <ul><li>Maintain an in-memory write buffer (bounded array, configurable max size, e.g., 10,000 events).</li><li>On <code>write()</code>: add event to buffer, trigger async persistence (do not await).</li><li>If persistence fails: keep event in buffer, schedule retry with exponential backoff.</li><li>If buffer is full: trigger immediate overflow to persistent storage (WP02); if overflow also fails, log a critical alert but NEVER drop the event (expand buffer temporarily).</li><li>On <code>flush()</code>: persist all buffered events synchronously.</li></ul></li><li>Add metrics: total events written, buffer high-water mark, persistence failures, retry count.</li><li>Ensure <code>write()</code> returns in &lt; 1ms (just buffer append, not persistence).</li><li>The sink delegates actual persistence to a storage backend (provided by WP02); for now, use a no-op or in-memory storage placeholder.</li><li>Export the sink for use by all audit producers.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/sink.ts</code></li></ul></li><li>Acceptance: <ul><li><code>write()</code> is non-blocking (&lt; 1ms).</li><li>Events are never dropped (buffer expands if needed).</li><li>Flush persists all buffered events.</li><li>Metrics track buffer health.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-subscribe-auditsink-to-local-bus-for-automatic-capture" tabindex="-1">Subtask T003 - Subscribe AuditSink to local bus for automatic capture <a class="header-anchor" href="#subtask-t003-subscribe-auditsink-to-local-bus-for-automatic-capture" aria-label="Permalink to &quot;Subtask T003 - Subscribe AuditSink to local bus for automatic capture&quot;">​</a></h3><ul><li>Purpose: Ensure all lifecycle events published on the local bus are automatically captured as audit events without manual instrumentation in every producer.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/bus-subscriber.ts</code>.</li><li>Define a mapping from bus event topics to audit event types: <ul><li><code>lane.*</code> events -&gt; <code>&quot;lane.lifecycle&quot;</code> audit events</li><li><code>session.*</code> events -&gt; <code>&quot;session.lifecycle&quot;</code> audit events</li><li><code>terminal.*</code> events -&gt; <code>&quot;terminal.lifecycle&quot;</code> audit events</li><li><code>policy.*</code> events -&gt; <code>&quot;policy.evaluation&quot;</code> audit events</li><li><code>approval.*</code> events -&gt; <code>&quot;approval.lifecycle&quot;</code> audit events</li></ul></li><li>Subscribe to all mapped bus topics.</li><li>For each received bus event, extract the relevant fields (actor, action, target, context IDs, correlation ID) and create an AuditEvent via the factory function.</li><li>Write the AuditEvent to the AuditSink.</li><li>Handle unrecognized bus topics: log a warning but do not crash; optionally create a generic audit event.</li><li>Ensure the subscription does not block the bus event dispatch (async handler).</li><li>Wire the subscriber into the runtime initialization so it starts capturing events from boot.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/bus-subscriber.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/index.ts</code> (wire subscriber at startup)</li></ul></li><li>Acceptance: <ul><li>Bus events are automatically captured as audit events.</li><li>Topic-to-event-type mapping covers all known topics.</li><li>Subscription is non-blocking.</li><li>Unknown topics handled gracefully.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-add-unit-tests-for-event-schema-sink-and-bus-subscriber" tabindex="-1">Subtask T004 - Add unit tests for event schema, sink, and bus subscriber <a class="header-anchor" href="#subtask-t004-add-unit-tests-for-event-schema-sink-and-bus-subscriber" aria-label="Permalink to &quot;Subtask T004 - Add unit tests for event schema, sink, and bus subscriber&quot;">​</a></h3><ul><li>Purpose: Lock the audit foundation behavior before building higher-level features.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/event.test.ts</code>: <ul><li>Test: factory function creates valid events with all required fields.</li><li>Test: missing required fields (actor, action, target) are caught by validation.</li><li>Test: UUID v7 IDs are time-ordered (event created later has lexicographically greater ID).</li><li>Test: metadata field accepts arbitrary key-value pairs.</li></ul></li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/sink.test.ts</code>: <ul><li>Test: <code>write()</code> returns in &lt; 1ms (non-blocking).</li><li>Test: write 10,000 events, flush, verify all persisted (using mock storage).</li><li>Test: simulate storage failure, verify events buffered and not lost.</li><li>Test: simulate storage recovery, verify buffered events are persisted on retry.</li><li>Test: buffer high-water mark metric tracks correctly.</li><li>Test: p95 write latency &lt; 5ms benchmark.</li></ul></li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/bus-subscriber.test.ts</code>: <ul><li>Test: bus event for <code>lane.created</code> topic produces a <code>lane.lifecycle</code> audit event.</li><li>Test: bus event for <code>policy.evaluation.completed</code> produces a <code>policy.evaluation</code> audit event.</li><li>Test: unknown bus topic produces warning log but no crash.</li><li>Test: correlation ID is preserved from bus event to audit event.</li></ul></li><li>Ensure all tests are deterministic and run via <code>bun test</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/event.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/sink.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/audit/bus-subscriber.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All tests pass.</li><li>Coverage of happy path, error paths, and edge cases.</li><li>Performance benchmarks pass.</li></ul></li><li>Parallel: Yes (after T001-T003 interfaces are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Unit tests for schema validation and factory functions.</li><li>Sink tests with mock storage backend.</li><li>Bus subscriber tests with mock bus.</li><li>Performance benchmarks for write latency.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: High event throughput overwhelms the buffer.</li><li>Mitigation: Bounded backpressure with overflow to persistent storage; critical alerts on buffer growth.</li><li>Risk: Storage backend not yet implemented (WP02).</li><li>Mitigation: Use mock/no-op storage; sink is decoupled from storage backend.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm all required audit event fields are present.</li><li>Confirm sink never blocks (&lt; 1ms write, &lt; 5ms p95 including async persistence).</li><li>Confirm events are never dropped (verify buffer behavior under failure).</li><li>Confirm bus subscriber covers all known topic categories.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:29:54Z – claude-haiku – shell_pid=55466 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:32:03Z – claude-haiku – shell_pid=55466 – lane=done – Implemented: Audit event schema, sink with non-blocking write, bus subscriber, and comprehensive unit tests</li></ul>',28)])])}const m=t(s,[["render",l]]);export{h as __pageData,m as default};
